CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL,image_url TEXT NOT NULL,seo_title TEXT,meta_description TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,category_slug TEXT NOT NULL,price REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'PKR',image_url TEXT NOT NULL,image_alt TEXT,short_description TEXT NOT NULL,description TEXT NOT NULL,sku TEXT NOT NULL UNIQUE,brand TEXT,availability TEXT NOT NULL DEFAULT 'InStock',specs_json TEXT NOT NULL DEFAULT '{}',seo_title TEXT,meta_description TEXT,canonical_url TEXT,is_indexable INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_products_category ON products(category_slug);
